// ===================================================
//
//  Ice Cubes visualizer by one and only - Orblivius!
//  Enjoy, and Happy New Year for all of us, hopefully.
//
//  Sources: https://shadertoy.com/view/lXycRG
//
// ===================================================


#define rot(a) mat2(cos(a+vec4(0,11,33,0)))

//formula for creating colors;
#define H(h)  (  cos( h*2. + 7.*vec3(1,2,3) )*.4 + .3 )

//formula for mapping scale factor 
#define M(c)  log(1.+c)

#define R iResolution

void mainImage( out vec4 O, vec2 U) {


    float wfac = .6, zoom=2., cfac=0.;

    if (mod(iTime,16.)>8.) {wfac=2.;zoom=-2.4;cfac=.1;} //play with this

    O = vec4(0); 
    vec3 c=vec3(0);  
    vec4 rd = normalize( vec4(U-.5*R.xy, .8*R.y, wfac*R.y))*12.; 

    float sc,dotp,totdist=0., t=iTime/2.;

    float fac=.54;

    if (iMouse.z > 0.) { 
        fac += (iMouse.x/R.x-.5)*.25; 
        zoom = (iMouse.y/R.y-.5)*2.;
    }
    else if (wfac == .6) {
        fac -= min(.065,max( .5*sin(t*2.),0.));
    }

    float psnd = 0.0;
    for (float i=0.; i<100.; i++) {

        float snd = 1.6-.45*(psnd+texture(iChannel0, vec2(clamp(i/100.,0.,.3),0.)).r);
        vec4 p = vec4( rd*totdist );

        p.z +=  .5*snd-.9+zoom*.5 + .325*sqrt(snd);

        p.xy *= rot(.707 + sin(t*snd*.01-iTime) );
        p.yz *= rot(.707 + cos(t*snd*.01-iTime) );
        p.xz *= rot(.707 + fract(iTime));

        sc = (1.-.35*(snd));  

        for (float j=0.; j<5.; j++) {

            p = abs(p)*(.45+cfac/3.+.25*sqrt(snd));

            dotp = max(1./dot(p,p),fac);
            sc *= dotp;

            p=p.x<p.y?p.wzxy:p.wzyx;
            p=p.z<p.w?p.xywz:p.xyzw;
            p=p.y<p.z?p.xwyz:p.xwzy;

            p *= max(dotp - .25*p + .1*sqrt(snd),-.15);
            psnd = snd;
        }


        float dist = clamp(abs( length(p-p.w) -.4-cfac/4.)/(1.+sc),3e-5,.01) ; 
        float stepsize = dist + 1e-6 ;
        totdist += stepsize;    

        c += (.25-cfac) *H(M(sc))*  exp(-i*i*stepsize*stepsize*8e2);
    }

    c = clamp(c,-100.,100.);

    c = 1. - exp(-c*c);

    c *= exp(-totdist*totdist/2.);

    c.b *= 1.5*(1.+3.*cfac);

    O = ( vec4(c,0) );

}
